	chainNvJitLinkComplete.bound = ""
	symcomplete = 0
	chainNvJitLinkCreate.bound = ""
	symCreate = 0
	chainNvJitLinkDestroy.bound = ""
	symdestroy = 0
	chainNvJitLinkGetErrorLog.bound = ""
	symgetErrorLog = 0
	chainNvJitLinkGetErrorLogSize.bound = ""
	symgetErrorLogSize = 0
